var scene = get_tree().current_scene
var results = []
for device in [1, 2, 3, 0]:
	var before = scene.samples.size()
	for value in [0.0, 0.95, 0.0]:
		var event = InputEventJoypadMotion.new()
		event.device = device
		event.axis = JOY_AXIS_RIGHT_X
		event.axis_value = value
		Input.parse_input_event(event)
		for frame in range(5):
			await get_tree().process_frame
	results.append({"device":device,"new_samples":scene.samples.size()-before})
return {"results":results,"log_rows":scene.log_rows}
